/* Ships & Boats set additions — cards appended after ships.js.
   Must stay directly after 'ships.js' in sets/manifest.js. */
(function () {
  var S = window.CardSets && window.CardSets.get('ships');
  if (!S) return;
  var extra = [{"name":"Delta Queen","rarity":"legendary","id":"delta-queen","subtitle":"Riverboat","details":"Sternwheel steamboat built in 1927 for California's river trade; a National Historic Landmark famed for decades of Mississippi River cruising.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/DeltaQueen.jpg?width=1023"},{"name":"PS Waverley","rarity":"legendary","id":"ps-waverley","subtitle":"Paddle Steamer","details":"Built in 1946, the world's last seagoing passenger paddle steamer; saved from scrap in 1974 and famed for cruises around the British coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PS_Waverley01.JPG?width=1024"},{"name":"SS Badger","rarity":"legendary","id":"ss-badger","subtitle":"Ferry","details":"Coal-fired Lake Michigan car ferry launched in 1952, carrying cars and passengers between Ludington, Michigan, and Manitowoc, Wisconsin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Badger_2025.jpg?width=1024"},{"name":"MV Kalakala","rarity":"legendary","id":"mv-kalakala","subtitle":"Ferry","details":"Puget Sound ferry with a welded, art-deco streamlined body built in 1934 over a 1926 hull; a Seattle icon until her retirement in 1967.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kalakala.jpg?width=609"},{"name":"American Queen","rarity":"epic","id":"american-queen","subtitle":"Riverboat","details":"Launched in 1995 and billed as the largest river steamboat ever built, a six-deck sternwheeler built for Mississippi River cruising.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/American_Queen_Eads_Bridge.jpg?width=1024"},{"name":"Belle of Louisville","rarity":"epic","id":"belle-of-louisville","subtitle":"Riverboat","details":"Steamboat launched in 1914 as Idlewild; renamed Belle of Louisville in 1962, she is famed for Kentucky Derby week's Great Steamboat Race.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Belle_of_Louisville_2.jpg?width=1024"},{"name":"Natchez","rarity":"epic","id":"natchez","subtitle":"Steamboat","details":"Sternwheel steamboat launched in 1975 at Braithwaite, Louisiana, her steam engines salvaged from a 1925 towboat; a New Orleans harbor landmark.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Steamboat_Natchez._New_Orleans._(48759732042).jpg?width=1024"},{"name":"Goldenrod","rarity":"epic","id":"goldenrod","subtitle":"Showboat","details":"Floating theatre launched in 1909, the last showboat built for the Mississippi trade and a National Historic Landmark long moored at St. Louis.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Goldenrod_Showboat_St.Louis.jpg?width=1024"},{"name":"TSS Earnslaw","rarity":"epic","id":"tss-earnslaw","subtitle":"Steamer","details":"Coal-fired Edwardian steamer launched in 1912; the only coal-fired passenger steamship in commercial service in the Southern Hemisphere.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/TSS_Earnslaw.jpg?width=1024"},{"name":"John J. Harvey","rarity":"epic","id":"john-j-harvey","subtitle":"Fireboat","details":"New York fireboat launched in 1931, among the most powerful ever built; recalled to pump water for 80 hours after the 9/11 attacks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fireboat_John_J._Harvey_1.jpg?width=1024"},{"name":"Lightship Ambrose","rarity":"epic","id":"lightship-ambrose","subtitle":"Lightship","details":"Steel lightship built in 1907 to mark Ambrose Channel at the entrance to New York Harbor; preserved at the South Street Seaport Museum.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/WTM_tony_0111.jpg?width=1024"},{"name":"Robert E. Lee","rarity":"rare","id":"robert-e-lee","subtitle":"Steamboat","details":"Mississippi steamboat built in 1866, the 'Monarch of the Mississippi', famed for winning the great 1870 race against Natchez to St. Louis.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Robert_E_Lee_Steamboat.jpg?width=1024"},{"name":"J.M. White","rarity":"rare","id":"jm-white","subtitle":"Steamboat","details":"Palatial Mississippi packet built in 1878 at Jeffersonville, among the largest and most luxurious river steamers of her era; burned in 1886.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/J._M._White_(1878_steamboat).jpg?width=1024"},{"name":"Julia Belle Swain","rarity":"rare","id":"julia-belle-swain","subtitle":"Riverboat","details":"Steam sternwheeler built in 1971 by Captain Dennis Trone at Dubuque, Iowa, one of the last steam sternwheelers built for American rivers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/JuilaBelleSwain.jpg?width=1024"},{"name":"SS Klondike","rarity":"rare","id":"ss-klondike","subtitle":"Sternwheeler","details":"The second Klondike, a 1937 sternwheeler that hauled freight between Whitehorse and Dawson City; now a National Historic Site at Whitehorse.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Klondike_03.jpg?width=1024"},{"name":"Keno","rarity":"rare","id":"keno","subtitle":"Sternwheeler","details":"Yukon sternwheeler constructed in 1922 at Whitehorse; her last voyage in 1960 took her to Dawson City as a National Historic Site museum ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Keno_Dawson.jpg?width=1024"},{"name":"Nenana","rarity":"rare","id":"nenana","subtitle":"Sternwheeler","details":"Wooden sternwheeler launched in 1933 at Nenana for the Alaska Railroad; the only surviving large wooden sternwheeler, preserved at Fairbanks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Nenana_sternwheeler_2011.jpg?width=1024"},{"name":"PS Kingswear Castle","rarity":"rare","id":"ps-kingswear-castle","subtitle":"Paddle Steamer","details":"Coal-fired paddle steamer dating from 1924 with engines from 1904, long associated with the River Dart after years of Medway excursions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PS_Kingswear_Castle01.JPG?width=1024"},{"name":"PS Maid of the Loch","rarity":"rare","id":"ps-maid-of-the-loch","subtitle":"Paddle Steamer","details":"The last paddle steamer built in Britain, launched in 1953 for Loch Lomond and assembled at Balloch after her sections travelled by rail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PS_Maid_of_the_Loch_2004.jpg?width=1024"},{"name":"SS Sir Walter Scott","rarity":"rare","id":"ss-sir-walter-scott","subtitle":"Steamer","details":"Steamship built in 1899 that has cruised Scotland's Loch Katrine for over a century, the sole surviving screw steamer in regular Scottish service.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sir_Walter_Scott_at_Trossachs_Pier_-_geograph.org.uk_-_144100.jpg?width=1024"},{"name":"MV Coho","rarity":"rare","id":"mv-coho","subtitle":"Ferry","details":"Black Ball ferry launched in 1959, carrying passengers and vehicles across the Strait of Juan de Fuca between Victoria and Port Angeles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2021-11-19_01_MV_COHO_-_IMO_5076949,_leaving_Port_Angeles,_WA_USA.jpg?width=1024"},{"name":"Spirit of British Columbia","rarity":"rare","id":"spirit-of-british-columbia","subtitle":"Ferry","details":"S-class BC Ferries flagship completed in 1993, among the largest ships in the fleet on the Tsawwassen to Swartz Bay route.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SpiritOfBritishColumbia.jpg?width=966"},{"name":"Hercules","rarity":"rare","id":"hercules","subtitle":"Tug","details":"Steam tug built in 1907 in New Jersey for San Francisco's Red Stack fleet; she towed great liners and is preserved at Hyde Street Pier.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hercules_Tugboat._(9618561221).jpg?width=1024"},{"name":"Edward M. Cotter","rarity":"rare","id":"edward-m-cotter","subtitle":"Fireboat","details":"Buffalo fireboat built in 1900 as William S. Grattan; the oldest active fireboat in the United States, doubling as a Lake Erie icebreaker.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cotter2017.jpg?width=1024"},{"name":"Nantucket Lightship","rarity":"rare","id":"nantucket-lightship","subtitle":"Lightship","details":"LV-112, built in 1936 as the largest American lightship of her day, stood watch at Nantucket Shoals and was the last lightship in US service.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lightship_Nantucket_(LV-112)_in_Boston_harbor_2018_crop.agr.jpg?width=1024"},{"name":"SS Moyie","rarity":"rare","id":"ss-moyie","subtitle":"Sternwheeler","details":"Sternwheeler assembled at Nelson in 1898 that served Kootenay Lake for nearly 60 years; restored as a museum ship at Kaslo, British Columbia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Moyie_(204922242).jpg?width=1024"},{"name":"MV Andrew J. Barberi","rarity":"uncommon","id":"mv-andrew-j-barberi","subtitle":"Ferry","details":"Staten Island ferry launched in 1981 with room for 6,000 passengers, among the highest-capacity ferryboats in the United States.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/NYC_Staten_Island_Ferry_Andrew_J._Barberi.jpg?width=1024"},{"name":"MV Tacoma","rarity":"uncommon","id":"mv-tacoma","subtitle":"Ferry","details":"Jumbo Mark-II ferry launched in 1997, first of her class for Washington State Ferries and a mainstay of the Seattle to Bainbridge route.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MV_Tacoma_entering_Elliott_Bay_01.jpg?width=1024"},{"name":"MV Wenatchee","rarity":"uncommon","id":"mv-wenatchee","subtitle":"Ferry","details":"Jumbo Mark-II ferry launched in 1998 for Washington State Ferries, second of her class after Tacoma, working Puget Sound crossings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/WA_Ferries_MV_Wenatchee.jpg?width=1024"},{"name":"MV Elwha","rarity":"uncommon","id":"mv-elwha","subtitle":"Ferry","details":"Super-class ferry that entered service in 1968 and spent most of her career on the Anacortes to San Juan Islands route; retired in 2020.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Elwha_passing_Flat_Point_04.JPG?width=1024"},{"name":"MV Freshwater","rarity":"uncommon","id":"mv-freshwater","subtitle":"Ferry","details":"Lead ship of Sydney's Freshwater-class Manly ferries, launched in 1982 for the Circular Quay to Manly run across Sydney Harbour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sydney_Ferry_FRESHWATER_approaching_Manly.jpg?width=1024"},{"name":"MV Queenscliff","rarity":"uncommon","id":"mv-queenscliff","subtitle":"Ferry","details":"Vehicle ferry launched in 1992 for the Queenscliff to Sorrento crossing of Port Phillip Bay in Victoria, Australia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Searoad_Ferry_'Queenscliff',_Queenscliff,_jjron,_06.07.2010.jpg?width=1024"},{"name":"MV Paşabahçe","rarity":"uncommon","id":"mv-pasabahce","subtitle":"Ferry","details":"Istanbul ferry built in Italy in 1952, the first postwar ship ordered for the city fleet; her speed made an Istanbul to Yalova service possible.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pa%C5%9Fabah%C3%A7e_ferry,_June_2023_(1).jpg?width=1024"},{"name":"Morning Star","rarity":"uncommon","id":"morning-star","subtitle":"Ferry","details":"Hong Kong Star Ferry boat built in 1965 and named for the 1871 original Morning Star; the oldest vessel in the Star Ferry fleet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Morning_Star_Star_Ferry_Central_to_Tsim_Sha_Tsui_17-05-2015.jpg?width=1024"},{"name":"Eppleton Hall","rarity":"uncommon","id":"eppleton-hall","subtitle":"Tug","details":"Paddle tug built on the Tyne in 1914, the last intact Tyne paddle tug; she crossed the Atlantic in 1969 to become a San Francisco museum ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eppleton_Hall_2_(15409666017).jpg?width=1024"},{"name":"Edmund Gardner","rarity":"uncommon","id":"edmund-gardner","subtitle":"Pilot Boat","details":"Pilot boat built in 1953 for the Liverpool pilot service, guiding ships across the Mersey Bar; preserved at the Merseyside Maritime Museum.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Edmund_Gardner_dazzle_ship.jpg?width=1024"},{"name":"Duwamish","rarity":"uncommon","id":"duwamish","subtitle":"Fireboat","details":"Seattle fireboat launched in 1909 with a riveted steel hull, the second-oldest purpose-built fireboat in the United States.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Duwamish_fire_boat.jpg?width=1024"},{"name":"Lydia Eva","rarity":"uncommon","id":"lydia-eva","subtitle":"Drifter","details":"The last surviving steam drifter of Great Yarmouth's herring fleet, built in 1930 and preserved as a museum ship in Norfolk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Steam_Drifter_Lydia_Eva.jpg?width=1024"},{"name":"Reaper","rarity":"uncommon","id":"reaper","subtitle":"Drifter","details":"Sailing herring drifter of the Fifie type, built in 1901 at Sandhaven in Scotland and preserved as a museum ship at Anstruther.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Reaper_in_sail.jpg?width=1024"},{"name":"Swiftsure Lightship","rarity":"uncommon","id":"swiftsure-lightship","subtitle":"Lightship","details":"Lightship built in 1904, the oldest surviving American lightship and the only one keeping her original steam engine; a Seattle museum ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/US_lightship_Swiftsure_(LV-83),_IMG-A.jpg?width=1024"},{"name":"RNLB H. F. Bailey","rarity":"uncommon","id":"rn-lb-h-f-bailey","subtitle":"Lifeboat","details":"Cromer lifeboat of the 1920s and 1930s, launched on famous rescues under coxswain Henry Blogg, the RNLI's most decorated lifeboatman.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cromer_Lifeboat_H_F_Bailey.jpg?width=1024"},{"name":"PS Ryde","rarity":"uncommon","id":"ps-ryde","subtitle":"Paddle Steamer","details":"Paddle steamer built in 1937 for Southern Railway's Portsmouth to Ryde ferry service; she ended her days derelict at Island Harbour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Paddle_Steamer_Ryde.jpg?width=1024"},{"name":"Minne-Ha-Ha","rarity":"uncommon","id":"minne-ha-ha","subtitle":"Sternwheeler","details":"Sternwheel steamboat christened in 1969 on Lake George, New York, one of the last steam paddlewheelers built in America; lengthened 34 feet in 1999.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Minne-Ha-Ha,_Lake_George,_New_York_(winter).jpg?width=1024"},{"name":"Discovery II","rarity":"uncommon","id":"discovery-ii","subtitle":"Sternwheeler","details":"Sternwheeler rebuilt in 1971 on the hull of the Yukon freighter Yutana, carrying tour passengers on the Chena and Tanana rivers at Fairbanks.","image":"https://en.wikipedia.org/wiki/Special:FilePath/DiscoveryII.jpg?width=1024"},{"name":"City of New Orleans","rarity":"uncommon","id":"city-of-new-orleans","subtitle":"Sternwheeler","details":"Sternwheeler built in 1991 as the casino boat Casino Rock Island; after a three-year renovation she joined the Natchez at New Orleans in 2020.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/City_of_New_Orleans_Riverboat_at_Woldenberg_Park,_New_Orleans,_January_2020_-_12.jpg?width=1024"},{"name":"SS Keewatin","rarity":"uncommon","id":"ss-keewatin","subtitle":"Steamer","details":"Edwardian passenger steamer built in Scotland in 1907 that linked Lake Superior and Georgian Bay ports for Canadian Pacific until 1965.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Keewatin_(2007).jpg?width=1024"},{"name":"RMS Segwun","rarity":"uncommon","id":"rms-segwun","subtitle":"Steamer","details":"Launched in 1887 as Nipissing and rebuilt as Segwun, the oldest operating steamship in North America, cruising Ontario's Muskoka Lakes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black_Smoke_from_the_Segwun.jpg?width=1024"},{"name":"Skibladner","rarity":"uncommon","id":"skibladner","subtitle":"Paddle Steamer","details":"Norwegian sidewheel paddle steamer whose maiden voyage came in 1856 on Lake Mjøsa; the world's oldest paddle steamer in timetabled service.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skibladner_Hamar_2015.jpg?width=1024"},{"name":"General Jackson","rarity":"common","id":"general-jackson","subtitle":"Showboat","details":"Showboat launched in 1985 for Nashville's Opryland, among the largest showboats ever built, cruising the Cumberland River at Nashville.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Genera_Jackson_riverboat_July_2018.jpg?width=1024"},{"name":"Delta King","rarity":"common","id":"delta-king","subtitle":"Riverboat","details":"Sternwheel steamboat built as Delta Queen's sister and launched in 1927; a moored hotel and theatre on Sacramento's Old Town waterfront.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Delta_King.JPG?width=1024"},{"name":"La Suisse","rarity":"common","id":"la-suisse","subtitle":"Paddle Steamer","details":"Lake Geneva paddle steamer launched in 1910, flagship of the CGN Belle Époque fleet and the largest paddle steamer on the lake.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/La_Suisse_(bateau).jpg?width=1024"},{"name":"Waimarie","rarity":"common","id":"waimarie","subtitle":"Paddle Steamer","details":"New Zealand's only coal-fired paddle steamer, built in 1899, raised from the Whanganui River in 1993 after 41 years sunk and restored.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Waimarie_paddle_steamer_on_Whanganui_River,_Whanganui.jpg?width=1024"},{"name":"PS Dresden","rarity":"common","id":"ps-dresden","subtitle":"Paddle Steamer","details":"Flagship of Dresden's Saxon paddle steamer fleet on the Elbe, launched in 1926, part of the world's oldest fleet of paddle steamers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2016_Dresden,_PS_Dresden,_011.jpg?width=1024"},{"name":"Hjejlen","rarity":"common","id":"hjejlen","subtitle":"Paddle Steamer","details":"Danish paddle steamer built in 1861, the world's oldest original coal-fired paddle steamer, sailing the Silkeborg lakes in Jutland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hjejlen.jpg?width=407"},{"name":"Stadt Luzern","rarity":"common","id":"stadt-luzern","subtitle":"Paddle Steamer","details":"Lake Lucerne's flagship paddle steamer, launched in 1928 and the last paddle steamer built for the lake's passenger fleet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dampfschiff_Stadt_Luzern_2013.jpg?width=1024"},{"name":"Uri","rarity":"common","id":"uri","subtitle":"Paddle Steamer","details":"Paddle steamer launched in 1901, the oldest ship in Lake Lucerne's fleet, working the Lucerne to Flüelen run beneath the Gotthard cliffs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1_DS_Uri_Fluelen_110616.jpg?width=1024"},{"name":"Hohentwiel","rarity":"common","id":"hohentwiel","subtitle":"Paddle Steamer","details":"The only paddle steamer on Lake Constance, launched in 1913 for the Württemberg state railways and saved by enthusiasts at Hard, Austria.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hard-Hohentwiel-01ASD.jpg?width=1024"},{"name":"PS Canberra","rarity":"common","id":"ps-canberra","subtitle":"Paddle Steamer","details":"Murray River paddle steamer built in 1912, part of the heritage fleet working from the historic wharf at Echuca in Victoria.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_River_Boat_Canberra_(8426021363).jpg?width=1024"},{"name":"PS Emmylou","rarity":"common","id":"ps-emmylou","subtitle":"Paddle Steamer","details":"Murray River paddle steamer launched in 1982 and named for singer Emmylou Harris, built for overnight cruising from Echuca.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CSIRO_ScienceImage_4620_Paddlesteamer_Emmylou_on_a_pleasure_cruise_down_the_Murray_River_steaming_past_the_old_wharf_at_Echuca_VIC.jpg?width=1024"},{"name":"PS Enterprise","rarity":"common","id":"ps-enterprise","subtitle":"Paddle Steamer","details":"Australian paddle steamer built in 1878 at Echuca, owned by the National Museum of Australia and among the world's oldest working paddle steamers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Paddle_Steamer_Enterprise_02.jpg?width=1024"},{"name":"PS Marion","rarity":"common","id":"ps-marion","subtitle":"Paddle Steamer","details":"Murray River paddle steamer dating from 1897, preserved at the dock museum at Mannum in South Australia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Paddlesteamer_the_Marion_on_River_Murray_-_Parliamentary_Tour_of_River_Murray(GN13980).jpg?width=1024"},{"name":"Furie","rarity":"common","id":"furie","subtitle":"Tug","details":"Dutch steam tug built in 1916, preserved at Maassluis and famous in the Netherlands as the star of the TV series Hollands Glorie.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Maassluis,_de_Furie_foto2_2008-10-04_13.27.JPG?width=1024"},{"name":"Mayflower (1861)","rarity":"common","id":"mayflower-tug","subtitle":"Tug","details":"Steam tug built in Bristol in 1861, the oldest Bristol-built ship afloat, preserved at the M Shed museum in the harbour where she worked.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Mayflower,_Floating_Harbour_-_geograph.org.uk_-_173688.jpg?width=1024"},{"name":"ST Portwey","rarity":"common","id":"st-portwey","subtitle":"Tug","details":"Steam tug built in 1927 by Harland and Wolff at Govan, the last surviving operational coal-fired twin-screw steam tug in Britain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Steam_tug_Portwey_-_geograph.org.uk_-_2210704.jpg?width=640"},{"name":"Daniel McAllister","rarity":"common","id":"daniel-mcallister","subtitle":"Tug","details":"Museum tug preserved in Montreal's Old Port, wearing the red and black of McAllister Towing, the fleet she served.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Le_remorqueur_Daniel_McAllister.jpg?width=1024"},{"name":"Lady Denman","rarity":"common","id":"lady-denman","subtitle":"Ferry","details":"Wooden Sydney Harbour ferry built in 1911, the last surviving timber ferry of her era, preserved at the Lady Denman Museum at Huskisson.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sydney_ferry_LADY_DENMAN_heading_for_Taronga_Zoo_1975.jpg?width=1024"},{"name":"MS Chi-Cheemaun","rarity":"common","id":"ms-chi-cheemaun","subtitle":"Ferry","details":"Lake Huron ferry launched in 1974 linking Tobermory with Manitoulin Island; her name is an Ojibwe word meaning 'big canoe'.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MS_Chi-Cheemaun_-_2017.jpg?width=1024"},{"name":"MV Ulysses","rarity":"common","id":"mv-ulysses","subtitle":"Ferry","details":"Irish Ferries flagship launched in 2000 for the Dublin to Holyhead route; at launch the world's largest car ferry by vehicle capacity.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ulysses_Arriving_In_Dublin.jpg?width=1024"},{"name":"PS Pillnitz","rarity":"common","id":"ps-pillnitz","subtitle":"Paddle Steamer","details":"Elbe paddle steamer launched in 1886, among the oldest of Dresden's Saxon fleet, named for the riverside palace at Pillnitz.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Elbdampfer_Pillnitz_passiert_Boje_bei_Kongresszentrum_2022.jpg?width=1024"},{"name":"Finngrundet","rarity":"common","id":"finngrundet","subtitle":"Lightship","details":"Swedish lightship built in 1903 that spent decades warning ships off the Finngrundet banks in the Sea of Åland; a Stockholm museum ship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lightship_Finngrundet.jpg?width=1024"},{"name":"RNLB Grace Darling","rarity":"common","id":"rn-lb-grace-darling","subtitle":"Lifeboat","details":"Seahouses RNLI lifeboat named for Grace Darling, the lighthouse keeper's daughter famed for the 1838 Forfarshire rescue.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/RNLI_Lifeboat_%22Grace_Darling%22_approaching_Seahouses_harbour_-_geograph.org.uk_-_3641935.jpg?width=1024"},{"name":"Creole Queen","rarity":"common","id":"creole-queen","subtitle":"Riverboat","details":"1,000-passenger paddlewheel riverboat built by Halter Marine at Moss Point, Mississippi in 1983, styled after a turn-of-the-century sternwheeler.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Creole_Queen_March_2016.jpg?width=1024"},{"name":"Rhône","rarity":"common","id":"rhone","subtitle":"Paddle Steamer","details":"Lake Geneva paddle steamer launched in 1927 for the CGN fleet, a Belle Époque survivor among the great Swiss lake steamers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bateau_%C3%A0_vapeur_Rhone_%C3%A0_aubes_Belle_%C3%89poque_Rh%C3%B4ne_sur_le_lac_Leman_en_Suisse.jpg?width=1024"},{"name":"PS Oscar W","rarity":"common","id":"ps-oscar-w","subtitle":"Paddle Steamer","details":"Wood-fired Murray River paddle steamer built in 1908, which hauled wool and supplies on the Darling trade and is preserved at Goolwa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Paddle_steamer_%22Oscar_W%22_at_Tailem_Bend,_South_Australia.JPG?width=1024"},{"name":"HMS Endeavour","rarity":"chase","id":"hms-endeavour","subtitle":"Explorer","details":"Cook's bark reached Australia's east coast in 1770 and charted New Zealand and the Great Barrier Reef.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/HMS_Endeavour_off_the_coast_of_New_Holland%2C_by_Samuel_Atkins_c.1794.jpg?width=1024"},{"name":"Kon-Tiki","rarity":"legendary","id":"kon-tiki","subtitle":"Raft","details":"Heyerdahl's balsa-log raft sailed 4,300 nautical miles from Peru to Polynesia in 101 days in 1947.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kon-Tiki%20raft%2C%20side%20view.jpg?width=1024"},{"name":"Fram","rarity":"legendary","id":"fram","subtitle":"Explorer","details":"Norwegian polar ship built to drift locked in ice: carried Nansen across the Arctic and Amundsen to the South Pole.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amundsen-Fram.jpg?width=1024"},{"name":"RV Calypso","rarity":"legendary","id":"rv-calypso","subtitle":"Research","details":"Cousteau's research ship, a converted minesweeper fitted with a bow observation chamber and a film studio at sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%22Calypso%22_-_Montreal%2C_1980.jpg?width=1024"},{"name":"Victoria","rarity":"epic","id":"victoria","subtitle":"Explorer","details":"The only ship of the Magellan-Elcano fleet to return to Spain in 1522, completing the first circumnavigation.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nao_Victoria.jpg?width=800"},{"name":"HMS Beagle","rarity":"epic","id":"hms-beagle","subtitle":"Explorer","details":"Survey brig whose 1831-36 voyage carried Charles Darwin around South America and the Galapagos.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/HMS%20Beagle%20by%20Conrad%20Martens.jpg?width=1024"},{"name":"HMS Challenger","rarity":"epic","id":"hms-challenger","subtitle":"Research","details":"Her 1872-76 expedition travelled nearly 69,000 nautical miles and founded modern oceanography.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/HMS_challenger_William_Frederick_Mitchell.jpg?width=1024"},{"name":"Gjøa","rarity":"epic","id":"gja","subtitle":"Explorer","details":"Amundsen's small sloop made the first complete transit of the Northwest Passage in 1903-06.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gjoea.jpg?width=1024"},{"name":"Hōkūleʻa","rarity":"epic","id":"hokulea","subtitle":"Canoe","details":"Polynesian double-hulled voyaging canoe that sailed Hawaii to Tahiti in 1976 guided without instruments.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hokule%27a.jpg?width=1024"},{"name":"HMS Resolution","rarity":"rare","id":"hms-resolution","subtitle":"Explorer","details":"Cook's flagship on his second and third voyages; first ship to cross the Antarctic Circle, in 1773.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hodges%2C_Resolution_and_Adventure_in_Matavai_Bay.jpg?width=1024"},{"name":"Turbinia","rarity":"rare","id":"turbinia","subtitle":"Steamer","details":"First steam-turbine vessel, launched in 1894; she dashed through the 1897 Spithead review at 34 knots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Turbinia_At_Speed.jpg?width=1024"},{"name":"Spray","rarity":"rare","id":"spray","subtitle":"Yacht","details":"Joshua Slocum rebuilt this oyster sloop and sailed her alone around the world in 1895-98, a first.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spray.jpg?width=1024"},{"name":"Gipsy Moth IV","rarity":"rare","id":"gipsy-moth-iv","subtitle":"Yacht","details":"Francis Chichester sailed her alone around the world in 1966-67 with a single stop, in Sydney.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gipsy_MothIV.jpg?width=1024"},{"name":"Suhaili","rarity":"rare","id":"suhaili","subtitle":"Yacht","details":"Robin Knox-Johnston's ketch won the 1968-69 Golden Globe as the first non-stop solo circumnavigation.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Suhaili.jpg?width=1024"},{"name":"Matthew","rarity":"rare","id":"matthew","subtitle":"Explorer","details":"John Cabot's small caravel reached the coast of North America from Bristol in 1497.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Mathew_cruising_Cardiff_Bay_%282799993543%29.jpg?width=1024"},{"name":"SS Savannah","rarity":"rare","id":"ss-savannah","subtitle":"Steamer","details":"In 1819 she became the first steamship to cross the Atlantic, Savannah to Liverpool, using steam for part of the way.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS-Savannah.jpg?width=1024"},{"name":"Great Western","rarity":"rare","id":"great-western","subtitle":"Steamer","details":"Brunel's wooden paddle steamer of 1838, built for the Bristol-New York run and an early Atlantic record-breaker.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Steamer_Great_Western_of_Bristol_RMG_A7626.jpg?width=1024"},{"name":"Ra II","rarity":"rare","id":"ra-ii","subtitle":"Raft","details":"Heyerdahl's papyrus boat crossed the Atlantic from Morocco to Barbados in 57 days in 1970.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/G%C3%BC%C3%ADmar%20Ra%20II%20BW%201.JPG?width=1024"},{"name":"Spirit of Australia","rarity":"rare","id":"spirit-of-australia","subtitle":"Speedboat","details":"Ken Warby's jet boat set the world water speed record of 317 mph on Blowering Dam in 1978.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spirit_of_Australia.jpg?width=1024"},{"name":"Sirius","rarity":"uncommon","id":"sirius","subtitle":"Steamer","details":"In 1838 she crossed from Cork to New York under steam alone, beating Brunel's Great Western into port.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS%20Sirius%20%281837%29.jpg?width=1024"},{"name":"Ella's Pink Lady","rarity":"uncommon","id":"ella-s-pink-lady","subtitle":"Yacht","details":"Jessica Watson sailed this pink sloop solo, non-stop and unassisted around the world in 2009-10, aged 16.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pink%20Lady%20at%20ANMM.jpg?width=1024"},{"name":"Guppy","rarity":"uncommon","id":"guppy","subtitle":"Yacht","details":"Laura Dekker's ketch carried her on a solo circumnavigation in 2011-12; she finished aged 16.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Segeljacht%20Guppy%20in%20Den%20Osse.jpg?width=1024"},{"name":"Quest","rarity":"uncommon","id":"quest","subtitle":"Explorer","details":"Shackleton's last expedition ship of 1921-22; he died aboard her at South Georgia in January 1922.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/FW%20SLV%20Quest%20in%20the%20Pack%20114.jpg?width=1024"},{"name":"Banque Populaire V","rarity":"uncommon","id":"banque-populaire-v","subtitle":"Trimaran","details":"Loick Peyron's giant trimaran set a crewed round-the-world record of 45 days 13 hours in 2012.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Banque%20Populaire%20V.jpg?width=1024"},{"name":"Tigris","rarity":"uncommon","id":"tigris","subtitle":"Raft","details":"Heyerdahl's reed ship sailed from Iraq toward the Horn of Africa in 1977-78 to test ancient sea routes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tigris%20crew.jpg?width=1024"},{"name":"Alcyone","rarity":"uncommon","id":"alcyone","subtitle":"Research","details":"Cousteau's second expedition ship, launched in 1985 with twin Turbosail rigs instead of cloth sails.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alcyone%20-%20Jacques%20Cousteau%27s%20Turbosail%20Ship%20-%20Caen%2C%20northwestern%20France%20-%20June%202011.jpg?width=1024"},{"name":"RV Atlantis","rarity":"uncommon","id":"rv-atlantis","subtitle":"Research","details":"Woods Hole research vessel launched in 1997, built to support the deep submersible Alvin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Research_Vessel_Atlantis.jpg?width=1024"},{"name":"Draken Harald Hårfagre","rarity":"uncommon","id":"draken-harald-harfagre","subtitle":"Longship","details":"The largest Viking longship built in modern times, launched in 2012; she crossed the Atlantic in 2016.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Seilet_heises_ombord_i_%22Draken_Harald_H%C3%A5rfagre%22_ved_Fjellsk%C3%A5lnes_i_Osterfjorden.jpg?width=1024"},{"name":"Sea Stallion from Glendalough","rarity":"uncommon","id":"sea-stallion-from-glendalough","subtitle":"Longship","details":"A full replica of the Skuldelev 2 warship, built in Denmark and sailed to Ireland in 2007.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sea%20Stallion%20lowering%20sail.jpg?width=1024"},{"name":"B&Q/Castorama","rarity":"uncommon","id":"b-and-q-castorama","subtitle":"Trimaran","details":"Ellen MacArthur's 75-foot trimaran set a solo non-stop round-the-world record of 71 days in 2005.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trimaran-B%26Q-Castorama.jpg?width=1024"},{"name":"IDEC Sport","rarity":"uncommon","id":"idec-sport","subtitle":"Trimaran","details":"Francis Joyon's trimaran set a crewed round-the-world record of under 41 days in 2017.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Groupama_3_under_sails%2C_South_Britanny%2C_front_side_view.jpg?width=1024"},{"name":"Sodebo Ultim","rarity":"uncommon","id":"sodebo-ultim","subtitle":"Trimaran","details":"Thomas Coville's trimaran set a solo round-the-world record of 49 days in 2016.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sodebo%20%2841440650870%29.jpg?width=1024"},{"name":"Belgica","rarity":"uncommon","id":"belgica","subtitle":"Explorer","details":"Her 1897-99 expedition was the first to winter in the Antarctic, beset in the Bellingshausen Sea ice.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/La_Belgica_1898_%28cropped%29.jpg?width=1024"},{"name":"RRS Discovery","rarity":"uncommon","id":"rrs-discovery","subtitle":"Research","details":"Built in Dundee for Antarctic work, she carried Scott and Shackleton south on the 1901-04 Discovery Expedition.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Discoveryboat.jpg?width=1024"},{"name":"Nimrod","rarity":"uncommon","id":"nimrod","subtitle":"Explorer","details":"Shackleton's expedition ship of 1907-09; her shore party reached a record farthest south of 88°23'S.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/NimrodDepartingToSouthPole1907.jpg?width=1024"},{"name":"Bluebird K7","rarity":"common","id":"bluebird-k7","subtitle":"Speedboat","details":"Donald Campbell's jet hydroplane set seven world water speed records between 1955 and 1964.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bluebird_K7_in_1960_at_Goodwood.jpg?width=1024"},{"name":"Terra Nova","rarity":"common","id":"terra-nova","subtitle":"Explorer","details":"A former whaler that carried Scott's last expedition to the Ross Sea in 1910-13.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Terra_Nova_ship_by_Herbert_Ponting%2C_1911.jpg?width=1024"},{"name":"SY Aurora","rarity":"common","id":"sy-aurora","subtitle":"Explorer","details":"Steam yacht that served Mawson's 1911-14 Antarctic expedition and Shackleton's Ross Sea party.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aurora_anchored_to_floe-ice_off_the_West_Base.jpg?width=1024"},{"name":"Maud","rarity":"common","id":"maud","subtitle":"Explorer","details":"Amundsen's oak polar ship, built for an Arctic drift and used on his Northeast Passage voyage of 1918-25.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Polarskipet_Maud.jpg?width=1024"},{"name":"St. Roch","rarity":"common","id":"st-roch","subtitle":"Schooner","details":"Canadian schooner that traversed the Northwest Passage in both directions and circumnavigated North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/St._Roch_schooner_wintering_in_the_Beaufort_Sea.jpg?width=1024"},{"name":"Vega","rarity":"common","id":"vega","subtitle":"Steamer","details":"Nordenskiold's barque made the first transit of the Northeast Passage in 1878-79, wintering in the ice.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Vega.jpg?width=1024"},{"name":"Pourquoi-Pas","rarity":"common","id":"pourquoi-pas","subtitle":"Explorer","details":"Jean-Baptiste Charcot's polar barque, built for his 1908-10 French Antarctic expedition.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pourquoi-Pas%20%281908%29.jpg?width=1024"},{"name":"Gauss","rarity":"common","id":"gauss","subtitle":"Research","details":"German polar research ship of Drygalski's 1901-03 South Polar expedition, beset for a year off Antarctica.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gauss%20Ship.jpg?width=1024"},{"name":"Kainan Maru","rarity":"common","id":"kainan-maru","subtitle":"Explorer","details":"Small wooden vessel of Shirase's Japanese Antarctic Expedition of 1910-12, the first from Japan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kainan-Maru.JPG?width=1024"},{"name":"Viking (1893)","rarity":"common","id":"viking-1893","subtitle":"Longship","details":"A replica of the Gokstad ship sailed from Bergen to the Chicago World's Fair in 1893.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Viking%2C_replica_of_the_Gokstad_Viking_ship%2C_at_the_Chicago_World_Fair_1893.jpg?width=1024"},{"name":"SS Royal William","rarity":"common","id":"ss-royal-william","subtitle":"Steamer","details":"In 1833 she crossed from Quebec to London largely under steam, among the first steamships to do so.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SS_Royal_William_1834_painting.png?width=1024"},{"name":"Charlotte Dundas","rarity":"common","id":"charlotte-dundas","subtitle":"Steamboat","details":"Symington's 1802 steamboat towed barges on the Forth and Clyde Canal, an early practical steam vessel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Charlotte_dundas_drawing_bowie.jpg?width=1024"},{"name":"Clermont","rarity":"common","id":"clermont","subtitle":"Steamboat","details":"Fulton's 1807 steamboat ran New York to Albany and became the first commercially successful steamboat service.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Clermont_replica.jpg?width=1024"},{"name":"SS Archimedes","rarity":"common","id":"ss-archimedes","subtitle":"Steamer","details":"Built in 1839, she was the first steamship driven successfully by a screw propeller.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Archimedes%2C_fitted_with_Mr._F.P._Smith%27s_Patent_Screw_Propeller_-_off_The_Nore%2C_on_her_trip_from_Gravesend_to_Portsmouth_-_May_14th_1839_RMG_PY8879.jpg?width=1024"},{"name":"Joshua","rarity":"common","id":"joshua","subtitle":"Yacht","details":"Moitessier's steel ketch sailed one and a half times around the world in the 1968-69 Golden Globe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Joshua%20%281%29.JPG?width=1024"},{"name":"RV Polarstern","rarity":"common","id":"rv-polarstern","subtitle":"Research","details":"German research icebreaker that served as the base of the MOSAiC Arctic drift expedition of 2019-20.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Polarstern_awi_hg.jpg?width=1024"},{"name":"Lively Lady","rarity":"common","id":"lively-lady","subtitle":"Yacht","details":"Alec Rose sailed this yawl alone around the world in 1967-68 with stops in Australia and New Zealand.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sailing_Yacht_Lively_Lady%2C_Port_Solent%2C_Jun_2012.jpg?width=1024"},{"name":"Hydroptère","rarity":"common","id":"hydroptere","subtitle":"Trimaran","details":"French foiling trimaran that in 2009 became the first sailing craft to break 50 knots over 500 metres.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/L%27Hydropt%C3%A8re.JPG?width=1024"},{"name":"RRS Sir David Attenborough","rarity":"common","id":"rrs-sir-david-attenborough","subtitle":"Research","details":"British polar research ship launched in 2018; she carries the submersible nicknamed Boaty McBoatface.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/RRS_Sir_David_Attenborough_at_Liverpool_Cruise_Terminal_4.jpg?width=1024"},{"name":"Ever Given","rarity":"chase","id":"ever-given","subtitle":"Container Ship","details":"Evergreen container ship that blocked the Suez Canal for six days in March 2021, halting a tenth of world trade.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/IMO_9811000_EVER_GIVEN_%2809%29.JPG?width=1024"},{"name":"Seawise Giant","rarity":"legendary","id":"seawise-giant","subtitle":"Tanker","details":"The longest ship ever built at 458 metres; she sailed as Seawise Giant, Jahre Viking and Knock Nevis before scrapping.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%22Seawise%20Giant%22%20-%20Singapore%2C%201990.jpg?width=1024"},{"name":"Icon of the Seas","rarity":"legendary","id":"icon-of-the-seas","subtitle":"Cruise Ship","details":"Royal Caribbean's 2024 flagship and the largest cruise ship ever built, at about 250,000 gross tons and 5,600 guests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Icon_of_the_Seas_Puerto_Rico_2025_%28cropped%29.jpg?width=1024"},{"name":"Oasis of the Seas","rarity":"epic","id":"oasis-of-the-seas","subtitle":"Cruise Ship","details":"Royal Caribbean giant that entered service in 2009, leading a new class of ships split by a central open-air neighbourhood.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oasis_of_the_Seas_Departs_Port_Canaveral_%28September_2026%29.jpg?width=1024"},{"name":"Pioneering Spirit","rarity":"epic","id":"pioneering-spirit","subtitle":"Crane Vessel","details":"Allseas' twin-hulled leviathan, the largest construction vessel ever built, able to lift whole offshore platforms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pioneering_Spirit_%28ship%2C_2014%29_005.jpg?width=1024"},{"name":"BOKA Vanguard","rarity":"epic","id":"boka-vanguard","subtitle":"Heavy-Lift Ship","details":"The largest heavy-lift ship ever built, able to submerge its deck and carry cargoes up to 110,000 tonnes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/DOCKWISE_VANGUARD_%2814834467231%29.jpg?width=1024"},{"name":"Arktika","rarity":"epic","id":"arktika","subtitle":"Icebreaker","details":"Russia's Project 22220 nuclear icebreaker, launched in 2016 and able to break ice nearly three metres thick.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%D0%90%D1%80%D0%BA%D1%82%D0%B8%D0%BA%D0%B0_%D0%B2_%D0%B4%D0%BE%D0%BA%D0%B5_%D0%B8%D0%BC._%D0%92%D0%B5%D0%BB%D0%B5%D1%89%D0%B8%D0%BD%D1%81%D0%BA%D0%BE%D0%B3%D0%BE.jpg?width=1024"},{"name":"Symphony of the Seas","rarity":"epic","id":"symphony-of-the-seas","subtitle":"Cruise Ship","details":"Royal Caribbean's 2018 Oasis-class giant, with a Central Park at sea and room for more than 6,600 guests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Symphony_of_the_Seas_Nassau_%28cropped%29.jpg?width=1024"},{"name":"Emma Mærsk","rarity":"epic","id":"emma-maersk","subtitle":"Container Ship","details":"Maersk's 2006 E-class flagship, the largest container ship in the world when she entered service.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2023_Emma_Maersk_-_IMO_9321483_-_by_2eight_-_9SC4259.jpg?width=1024"},{"name":"Wonder of the Seas","rarity":"rare","id":"wonder-of-the-seas","subtitle":"Cruise Ship","details":"Oasis-class ship delivered in 2022, the largest cruise ship in the world at her launch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wonder_of_the_Seas_Jan_30_2025.jpg?width=1024"},{"name":"CSCL Globe","rarity":"rare","id":"cscl-globe","subtitle":"Container Ship","details":"China Shipping's 2014 giant, the largest container ship in the world when she entered service.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CSCL_Globe_arriving_at_Felixstowe%2C_United_Kingdom.jpg?width=1024"},{"name":"HMM Algeciras","rarity":"rare","id":"hmm-algeciras","subtitle":"Container Ship","details":"HMM's 2020 flagship class, among the largest container ships ever built at about 24,000 TEU.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/HMM_Algeciras_Arriving_in_Southampton_1.jpg?width=1024"},{"name":"MSC Gülsün","rarity":"rare","id":"msc-gulsun","subtitle":"Container Ship","details":"MSC's 2019 giant, the largest container ship in the world at her launch, at about 23,800 TEU.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MSC_G%C3%9CLS%C3%9CN_%2848675118678%29_%28cropped%29.jpg?width=1024"},{"name":"Ever Alot","rarity":"rare","id":"ever-alot","subtitle":"Container Ship","details":"Evergreen's 2022 A-class ship, one of the largest container ships ever built at about 24,000 TEU.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2025-10-19%20-%20EVER%20ALOT%2C%20Port%20of%20Felixstowe%20-%2001.jpg?width=1024"},{"name":"50 Let Pobedy","rarity":"rare","id":"50-let-pobedy","subtitle":"Icebreaker","details":"Russian nuclear icebreaker named for 50 years of victory; she carries tourists to the North Pole.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/50letPob_pole.JPG?width=1024"},{"name":"Batillus","rarity":"rare","id":"batillus","subtitle":"Tanker","details":"French supertanker of 1976, one of the largest ships ever built at over 550,000 tonnes deadweight.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Batillus_tanker_in_Saint-Nazaire.jpg?width=1024"},{"name":"TI Asia","rarity":"rare","id":"ti-asia","subtitle":"Tanker","details":"Ultra-large crude carrier, one of the largest double-hulled tankers ever built; she was launched as Hellespont Tara.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hellespont_Tara-023-cleaned.jpg?width=1024"},{"name":"SR.N4 Princess Margaret","rarity":"rare","id":"sr-n4-princess-margaret","subtitle":"Hovercraft","details":"Mountbatten-class hovercraft that crossed the English Channel in about 35 minutes, carrying cars and passengers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SRN4_Hovercraft_Mountbatten_Class.jpg?width=1024"},{"name":"Sibir","rarity":"uncommon","id":"sibir","subtitle":"Icebreaker","details":"Russia's second Project 22220 nuclear icebreaker, built to keep Arctic shipping lanes open year-round.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sibir%20%28Project%2022220%20nuclear-powered%20icebreaker%29%20in%20December%202018.%20Baltic%20Shipyard%2C%20St.%20Petersburg.jpg?width=800"},{"name":"Xue Long","rarity":"uncommon","id":"xue-long","subtitle":"Icebreaker","details":"China's first polar research icebreaker, bought from Ukraine in 1993 and rebuilt for Antarctic supply runs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Xue_Long%2C_Fremantle%2C_2016_%284%29.jpg?width=1024"},{"name":"Africa Mercy","rarity":"uncommon","id":"africa-mercy","subtitle":"Hospital Ship","details":"Mercy Ships' converted Danish rail ferry, fitted with hospital wards bringing free surgery to West Africa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Africa%20Mercy%20%C3%A0%20Conakry.jpg?width=1024"},{"name":"Global Mercy","rarity":"uncommon","id":"global-mercy","subtitle":"Hospital Ship","details":"The world's largest civilian hospital ship, built in China and delivered in 2021, with six operating theatres.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mercy_Ships_Rotterdam_%28cropped%29.jpg?width=1024"},{"name":"Jutlandia","rarity":"uncommon","id":"jutlandia","subtitle":"Hospital Ship","details":"Danish liner converted to a hospital ship for the Korean War, and the subject of a famous Danish song.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jutlandia.jpg?width=1024"},{"name":"PlanetSolar Tûranor","rarity":"uncommon","id":"planetsolar-turanor","subtitle":"Solar Boat","details":"Swiss solar catamaran that made the first solar-powered circumnavigation of the world, from 2010 to 2012.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PlanetSolar-In-Miami-Florida.jpg?width=1024"},{"name":"Mayflower Autonomous Ship","rarity":"uncommon","id":"mayflower-autonomous-ship","subtitle":"Autonomous Ship","details":"Crewless AI research ship that crossed the Atlantic in 2022, retracing the Mayflower's route 400 years on.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mayflower%20Autonomous%20Ship%20inside%20Plymouth%20Sound.jpg?width=1024"},{"name":"Alvin","rarity":"uncommon","id":"alvin","subtitle":"Submersible","details":"Deep-sea submersible that has made over 5,000 dives, including to the Titanic and hydrothermal vents.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/ALVIN_submersible.jpg?width=1024"},{"name":"Trieste","rarity":"uncommon","id":"trieste","subtitle":"Bathyscaphe","details":"Bathyscaphe that took Jacques Piccard and Don Walsh to the bottom of the Mariana Trench in 1960.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bathyscaphe_Trieste.jpg?width=1024"},{"name":"Limiting Factor","rarity":"uncommon","id":"limiting-factor","subtitle":"Submersible","details":"Two-person submersible that dived the deepest point of every ocean in the Five Deeps Expedition.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/DSV_Bakunawa_descending_underwater_%28cropped%29.jpg?width=1024"},{"name":"Jetfoil","rarity":"uncommon","id":"jetfoil","subtitle":"Hydrofoil","details":"Boeing's jet-powered hydrofoil ferry, which flew above the waves on foils at up to about 45 knots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/TurboJet_hydrofoil_Cacilhas_in_Hong_Kong_harbor.jpg?width=1024"},{"name":"Tres Hombres","rarity":"uncommon","id":"tres-hombres","subtitle":"Sailing Ship","details":"Dutch brigantine that carries fair-trade cargo across the Atlantic under sail, founded by three friends.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brest2012%20-%20Parade%20Douarnenez%2091.jpg?width=1024"},{"name":"Energy Observer","rarity":"uncommon","id":"energy-observer","subtitle":"Catamaran","details":"French catamaran that circumnavigated the globe on hydrogen and solar power, producing its own fuel at sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/14APR2017_Mise_%C3%A0_l%27eau_d%27Energy_Observer_1.jpg?width=1024"},{"name":"Allure of the Seas","rarity":"uncommon","id":"allure-of-the-seas","subtitle":"Cruise Ship","details":"Oasis-class sister ship delivered in 2010, with a boardwalk, zip line and a full-size carousel at sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Allure_of_the_Seas_%28ship%2C_2009%29_001.jpg?width=1024"},{"name":"Harmony of the Seas","rarity":"uncommon","id":"harmony-of-the-seas","subtitle":"Cruise Ship","details":"Oasis-class ship delivered in 2016, the largest passenger ship in the world at her launch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Harmony_of_the_Seas_Departs_Port_Canaveral_%28September_2026%29.jpg?width=1024"},{"name":"AIDAnova","rarity":"uncommon","id":"aidanova","subtitle":"Cruise Ship","details":"The first cruise ship powered entirely by liquefied natural gas, delivered in 2018.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/AIDAnova_29-04-2024.jpg?width=1024"},{"name":"MSC World Europa","rarity":"uncommon","id":"msc-world-europa","subtitle":"Cruise Ship","details":"MSC's 2022 LNG-powered flagship and the first of the World class, carrying over 6,700 guests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MSC_World_Europa_-_Saint-Nazaire_-_June_2022.jpg?width=1024"},{"name":"KM Ekranoplan","rarity":"uncommon","id":"km-ekranoplan","subtitle":"Ekranoplan","details":"The 'Caspian Sea Monster', a Soviet ground-effect craft that flew just above the water at over 400 km/h.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%D0%AD%D0%BA%D1%80%D0%B0%D0%BD%D0%BE%D0%BF%D0%BB%D0%B0%D0%BD_%D0%9A%D0%9C.jpg?width=1024"},{"name":"Dali","rarity":"uncommon","id":"dali","subtitle":"Container Ship","details":"Singapore-flagged container ship built in 2015; in March 2024 she struck Baltimore's Francis Scott Key Bridge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/DALI%20%2829715954007%29.jpg?width=1024"},{"name":"Ever Forward","rarity":"uncommon","id":"ever-forward","subtitle":"Container Ship","details":"Container ship that ran aground in Chesapeake Bay in March 2022 and took a month to refloat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20container%20ship%20Ever%20Forward%20-%20220420-A-OX377-2006.jpg?width=1024"},{"name":"Polarstern","rarity":"common","id":"polarstern","subtitle":"Icebreaker","details":"Germany's Alfred Wegener Institute research icebreaker, working both polar oceans since 1982.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Polarstern_awi_hg.jpg?width=1024"},{"name":"Akademik Mstislav Keldysh","rarity":"common","id":"akademik-mstislav-keldysh","subtitle":"Research Ship","details":"Russian research ship, mother ship of the Mir submersibles that filmed the Titanic wreck in the 1990s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Akademik_Mstislav_Keldysh.jpg?width=1024"},{"name":"Rainbow Warrior","rarity":"common","id":"rainbow-warrior","subtitle":"Sailing Ship","details":"Greenpeace's third Rainbow Warrior, a motor-assisted sailing ship launched in 2011 and built to campaign at sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/RWIII_2.jpg?width=1024"},{"name":"Arctic Sunrise","rarity":"common","id":"arctic-sunrise","subtitle":"Icebreaker","details":"Greenpeace's ice-strengthened campaign ship, built in 1975 and best known for Arctic protests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arcticsunrisedocked.jpg?width=1024"},{"name":"Falkor Too","rarity":"common","id":"falkor-too","subtitle":"Research Ship","details":"Schmidt Ocean Institute's research ship, successor to Falkor, carrying remotely operated vehicles to deep water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Falkor_%28too%29_vessel.jpg?width=1024"},{"name":"OceanXplorer","rarity":"common","id":"oceanxplorer","subtitle":"Research Ship","details":"OceanX's 87-metre research vessel, refitted with submersibles and labs for deep-ocean exploration.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Le%20navire%20OceanXplorer%20%C3%A0%20Nice%20durant%20l%27UNOC3%20%28Ifremer%2000958-107019%20-%2055664%29.jpg?width=1024"},{"name":"Xue Long 2","rarity":"common","id":"xue-long-2","subtitle":"Icebreaker","details":"China's first domestically built polar research icebreaker, delivered in 2019 for both polar regions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/202404_Xuelong-2_in_Hong_Kong.jpg?width=1024"},{"name":"Viktor Chernomyrdin","rarity":"common","id":"viktor-chernomyrdin","subtitle":"Icebreaker","details":"Russia's largest non-nuclear icebreaker, delivered in 2020 to work the Northern Sea Route.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%D0%9B%D0%B5%D0%B4%D0%BE%D0%BA%D0%BE%D0%BB_%22%D0%92%D0%B8%D0%BA%D1%82%D0%BE%D1%80_%D0%A7%D0%B5%D1%80%D0%BD%D0%BE%D0%BC%D1%8B%D1%80%D0%B4%D0%B8%D0%BD%22.jpg?width=1024"},{"name":"HSC Francisco","rarity":"common","id":"hsc-francisco","subtitle":"Ferry","details":"Buquebus catamaran ferry, one of the fastest ferries in the world at 58 knots, running between Argentina and Uruguay.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Francisco_D%C3%A1rsena_Norte_-_01.jpg?width=1024"},{"name":"MS Roald Amundsen","rarity":"common","id":"ms-roald-amundsen","subtitle":"Cruise Ship","details":"Hurtigruten's hybrid battery-assisted expedition ship, named for the polar explorer and delivered in 2019.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hurtigrutten_Roald_amundsen.jpg?width=1024"},{"name":"Fridtjof Nansen","rarity":"common","id":"fridtjof-nansen","subtitle":"Cruise Ship","details":"Hurtigruten's hybrid expedition ship, sister to Roald Amundsen, built for polar cruising.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fridtjof_Nansen_%28IMO_9813084%29_Lysefjord%2C_2025.jpg?width=1024"},{"name":"Norwegian Prima","rarity":"common","id":"norwegian-prima","subtitle":"Cruise Ship","details":"Norwegian's 2022 Prima-class lead ship, with a three-level go-kart track and an outdoor promenade.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Norwegian_Prima_Jan_19_2023.jpg?width=1024"},{"name":"Celebrity Apex","rarity":"common","id":"celebrity-apex","subtitle":"Cruise Ship","details":"Celebrity's second Edge-class ship, delivered in 2020, with a moving platform that cantilevers over the sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CELEBRITY%20APEX%2020-8-2025.jpg?width=1024"},{"name":"Scarlet Lady","rarity":"common","id":"scarlet-lady","subtitle":"Cruise Ship","details":"Virgin Voyages' first ship, delivered in 2020, an adults-only cruise ship with no buffet or formal nights.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scarlet_Lady_in_Liverpool_February_2020_%28cropped%29.jpg?width=1024"},{"name":"Carnival Jubilee","rarity":"common","id":"carnival-jubilee","subtitle":"Cruise Ship","details":"Carnival's 2023 Excel-class ship, with a roller coaster bolted to her top deck.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Carnival_Jubilee_Panorama_Cozumel_2024.jpg?width=1024"},{"name":"Sun Princess","rarity":"common","id":"sun-princess","subtitle":"Cruise Ship","details":"Princess Cruises' 2024 Sphere-class lead ship, powered by liquefied natural gas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sun_Princess_at_Piraeus_Harbour.jpg?width=1024"},{"name":"Disney Wish","rarity":"common","id":"disney-wish","subtitle":"Cruise Ship","details":"Disney's 2022 Wish-class ship, with a water coaster, a Star Wars lounge and fireworks at sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Disney_Wish_Departs_Port_Canaveral_%28September_2026%29.jpg?width=1024"},{"name":"Queen Anne","rarity":"common","id":"queen-anne","subtitle":"Cruise Ship","details":"Cunard's 2024 ship, the line's first new ship in 14 years and the 249th to sail under the Cunard flag.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MS%20Queen%20Anne%20at%20Cabo%20San%20Lucas%20Mexico%2031%20January%202025.jpg?width=1024"},{"name":"National Geographic Endurance","rarity":"common","id":"national-geographic-endurance","subtitle":"Expedition Ship","details":"Lindblad's purpose-built polar ship, named for Shackleton's Endurance and delivered in 2021.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/National_Geographic_Endurance_maiden_call_Kiel_XIV.jpg?width=1024"},{"name":"Silver Endeavour","rarity":"common","id":"silver-endeavour","subtitle":"Cruise Ship","details":"Silversea's ice-class expedition ship, built for luxury polar cruising and delivered in 2021.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Silver_Endeavour_-_Gerlache_Strait_-_Antarctica_-_V-P.jpg?width=1024"},{"name":"Le Commandant Charcot","rarity":"common","id":"le-commandant-charcot","subtitle":"Icebreaker","details":"PONANT's luxury polar exploration ship, a hybrid icebreaker able to reach the geographic North Pole.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Le_Commandant_Charcot_during_Operation_Tugaalik_in_June_23%2C_2024_%281%29.jpg?width=1024"},{"name":"AP1-88","rarity":"common","id":"ap1-88","subtitle":"Hovercraft","details":"British Hovercraft Corporation's workhorse hovercraft, used as ferries and patrol craft around the world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/AP1-88.jpg?width=1024"},{"name":"Lun Ekranoplan","rarity":"common","id":"lun-ekranoplan","subtitle":"Ekranoplan","details":"Soviet Lun-class ground-effect craft, armed with anti-ship missiles and now beached as a museum at Derbent.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lun-class_ekranoplan_%282026-03-18%29_-_0_4.jpg?width=1024"},{"name":"Maltese Falcon","rarity":"common","id":"maltese-falcon","subtitle":"Sailing Yacht","details":"A 289-foot yacht launched in 2006; her three free-standing masts rotate to set 25,791 square feet of sail by computer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Maltese_Falcon_sailboat_-_2_(3656924056).jpg?width=1024"},{"name":"Greg Mortimer","rarity":"common","id":"greg-mortimer","subtitle":"Cruise Ship","details":"Aurora Expeditions' 2019 polar ship, the first to use a wave-piercing X-Bow in expedition cruising.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Greg_Mortimer_IMO_9834648_P_Antarctica_03-01-2020.jpg?width=1024"},{"name":"Voskhod","rarity":"common","id":"voskhod","subtitle":"Hydrofoil","details":"Soviet hydrofoil passenger boat, built in large numbers to speed river travellers across the USSR.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Voskhod_24.jpg?width=1024"},{"name":"Grain de Sail","rarity":"common","id":"grain-de-sail","subtitle":"Sailing Ship","details":"French cargo sailing ship that carries wine and chocolate across the Atlantic under sail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Grain%20de%20Sail%2C%20Saint-Malo%2C%20November%202023.jpg?width=1024"},{"name":"Ilya Muromets","rarity":"common","id":"ilya-muromets","subtitle":"Icebreaker","details":"Project 97 diesel-electric icebreaker launched in 1965, named for the folk hero, working Soviet Far East waters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ledokol-Il%27yaMuromets%28DN-SC-91-01134%29.jpg?width=1024"},{"name":"RV Investigator","rarity":"common","id":"rv-investigator","subtitle":"Research Ship","details":"Australia's CSIRO marine research vessel, delivered in 2014, a floating laboratory with a 60-day endurance.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CSIRO_ScienceImage_2363_RV_Investigator_side_view.jpg?width=1024"},{"name":"Yamal","rarity":"common","id":"yamal","subtitle":"Icebreaker","details":"Russian nuclear icebreaker, launched in 1992, famous for the shark's mouth painted on her bow.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nuclearicebreakeryamal.jpg?width=1024"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
